from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", price="600.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(price))],status=status)

# basic
print(issue_credit_note(inv(), Decimal("10.00"), "goodwill"))
# zero/negative
for a in ("0.00","-1.00"):
    try: issue_credit_note(inv(), a, "x")
    except BillingError as e: print("err", e.code)
# exceeds total
try: issue_credit_note(inv(price="50.00"), "60.00", "x")
except BillingError as e: print("err", e.code)
# non-issued
try: issue_credit_note(inv(status="draft"), "10.00", "x")
