print(issue_credit_note(inv(), "500.00", "x")["amount"])
print(issue_credit_note(inv(), "500.01", "x", approved_by="mgr")["amount"])
# idempotency
audit.clear()
r1 = issue_credit_note(inv(), "10.00", "x", idempotency_key="k1")
r2 = issue_credit_note(inv(), "10.00", "x", idempotency_key="k1")
print(r1 == r2, len(audit.events("credit_note_issued")))
